input.command:
cd /Users/kristinarash/Library/Caches/sportsci-batch-123 && node -e '
const fs=require("fs");
const inputs=require("./inputs.json");
const tax=require("./taxonomy.json");
const ids=["Q25","Q26","Q27","Q28","Q29","Q30","Q31","Q32"];
for(const id of ids){
  const d=JSON.parse(fs.readFileSync(`drafts/${id}.json`,"utf8"));
  const inp=inputs.find(r=>r.id===id);
  const probs=[];
  if(d.sourceFile!==inp.sourceFile) probs.push("sourceFile mismatch");
  if(d.id!==id) probs.push("id");
  if(d.decision==="INCLUDE"){
    if(!d.domains.includes(d.primaryDomain)) probs.push("primary not in domains");
    if(!tax.domains.includes(d.primaryDomain)) probs.push("bad primaryDomain");
    if(!tax.studyDesigns.includes(d.studyDesign)) probs.push("bad design");
    for(const x of d.domains) if(!tax.domains.includes(x)) probs.push("bad domain "+x);
    for(const x of d.audiences) if(!tax.audiences.includes(x)) probs.push("bad aud "+x);
    for(const x of d.sports) if(!tax.sports.includes(x)) probs.push("bad sport "+x);
    for(const x of d.populations) if(!tax.populations.includes(x)) probs.push("bad pop "+x);
    if(d.paper.doi!==inp.externalDoi) probs.push("doi != externalDoi");
    if(d.paper.doi!==d.paper.doi.toLowerCase()) probs.push("doi case");
  }
  const txt=JSON.stringify(d);
  const emd=(txt.match(/—/g)||[]).length;
  console.log(id,d.decision,d.studyDesign||"-",d.paper?d.paper.year:"-",d.doiMissing,"emdash="+emd,probs.length?probs.join(";"):"OK");
}'; ls drafts; ls helpers/d04 2>/dev/null | wc -l

